import base64,json,datetime,re,os
def exp(tok,label):
    parts=tok.strip().strip('"\'').split('.')
    if len(parts)!=3: print(label,'not a JWT'); return
    p=parts[1]+'='*(-len(parts[1])%4)
    c=json.loads(base64.urlsafe_b64decode(p))
    e=c.get('exp'); print(label,'exp:', datetime.datetime.utcfromtimestamp(e).date() if e else None, 'iat:', datetime.datetime.utcfromtimestamp(c['iat']).date() if 'iat' in c else None)
for line in open('.env'):
    if line.startswith('CATAPULT_TOKEN='): exp(line.split('=',1)[1],'.env')
for line in open(os.path.expanduser('~/.local/share/catapult-openfield-connect-pp-cli/credentials.toml')):
    m=re.match(r'\s*access_token\s*=\s*(.+)',line)
    if m: exp(m.group(1),'credentials.toml')
EOF

